"""Per-check prose for the checks added in 1.2.0: record-level authorization, financial integrity, runtime profiling and live verification."""
T_NEW2 = {
"AUTHZ-001": ("A permission policy was written but no code ever asks it.", "A policy that is never called protects nothing; the app is as open as if it did not exist.", "Call `$this->authorize()` in each action, add `authorizeResource()` to the controller, or use `can:` middleware on the routes.", "A test as another user gets 403 on each action."),
"AUTHZ-002": ("A policy rule never compares the signed-in user with the record, so it answers the same for everyone.", "Any user passes the check for any record.", "Compare the record's owner or tenant with the user (`$user->id === $post->user_id`).", "A test as a user who does not own the record gets 403."),
"AUTHZ-003": ("This controller checks permission for some actions on a record but not for this one.", "Attackers use the unchecked action, for example delete, when view is protected.", "Authorise every action, or use `authorizeResource()` so none can be forgotten.", "Each action returns 403 for a user who may not do it."),
"AUTHZ-004": ("A policy rule always says yes.", "Every user is allowed to do that operation on every record.", "Return a real condition, or remove the rule so the default (deny) applies.", "A user without rights gets 403."),
"FIN-001": ("A balance is changed but no ledger or transaction row records why.", "Without a record you cannot explain, reconcile or reverse a balance, and bugs or fraud leave no trace.", "Write a ledger row (amount, direction, reason, reference) in the same database transaction as every balance change.", "Sum of ledger rows equals the balance for every account."),
"FIN-002": ("A transfer takes money from one account and never adds it to another.", "Money disappears, or is created, and the books stop balancing.", "Debit and credit in one transaction, with matching ledger rows.", "Total money before and after a transfer is equal."),
"FIN-003": ("A balance column can hold a negative number.", "Any race or bug can overdraw an account and the database will not stop it.", "Add a CHECK (balance >= 0) constraint or an unsigned column, in addition to the code check.", "An insert that would go negative is rejected by the database."),
"FIN-004": ("A payment, transfer or payout table has no unique key such as a reference or idempotency key.", "The same payment can be stored twice by a retry.", "Add a unique index on the provider reference or idempotency key.", "Inserting the same reference twice fails."),
"PERF-013": ("This page runs a very large number of database queries.", "Every query is a round trip; the page slows with data.", "Eager load, join, or cache; confirm with the profiler after.", "Query count drops below the threshold."),
"PERF-014": ("The same query ran many times while building one page (measured N+1).", "A confirmed N+1: cost grows with the number of rows.", "Load the relation up front with `with()`.", "Repeat count falls to 1."),
"PERF-015": ("A page is slow or uses a lot of memory.", "Slow pages lose users and big memory use crashes workers.", "Paginate, cache, queue heavy work and select fewer columns.", "Time and memory fall under the thresholds."),
"PROD-001": ("The site's HTTPS certificate is invalid or about to expire.", "Browsers will block the site and payment or login flows fail.", "Renew the certificate and turn on automatic renewal.", "The check reports more than 30 days left."),
"PROD-002": ("Plain HTTP is not redirected to HTTPS, or an outdated TLS version is accepted.", "Passwords and sessions can be read in transit.", "Redirect port 80 to HTTPS and allow TLS 1.2 and 1.3 only.", "`http://` returns a redirect to `https://`."),
"PROD-003": ("A sensitive file or debug tool answers on the live site.", "Environment files, logs and debug dashboards hand out secrets and data.", "Block the path at the web server, point the web root at `public`, remove the tool from production and rotate anything exposed.", "The path returns 403 or 404."),
"PROD-004": ("The scheduler, queue or backup has not reported recently on the live server.", "Scheduled work, queued mail or backups have stopped without anyone noticing.", "Restart the process, then add alerting on the health report.", "The health report shows recent activity."),
}
